mapper.sql:
WHERE p.state <> 'deleted'
AND p.board_id = #{boardId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR u.name LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT p.post_id AS postId, p.board_id AS boardId, b.name AS boardName, p.title, u.name AS authorName,
CASE WHEN u.is_deleted = 1 THEN NULL ELSE u.login_id END AS authorLoginId, CASE WHEN u.is_deleted = 1 THEN NULL ELSE u.student_no END AS authorStudentNo, (SELECT COUNT(*) FROM comments cm WHERE cm.post_id = p.post_id) AS commentCount, (SELECT COUNT(*) FROM post_likes pl WHERE pl.post_id = p.post_id) AS likeCount, p.view_count AS viewCount, p.created_at AS created, p.state FROM posts p INNER JOIN users u ON p.user_id = u.user_id INNER JOIN boards b ON p.board_id = b.board_id
ORDER BY p.created_at DESC LIMIT #{size} OFFSET #{offset}
